#pragma once

#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

/* Buffer sizes that are large enough for MAX_BITS (128) bits. */
#define WIEGAND_BINARY_TEXT_SIZE 200
#define WIEGAND_HEX_TEXT_SIZE    40
#define WIEGAND_DECODE_TEXT_SIZE 240

/** True when the bit count is one that a common credential format uses. */
bool wiegand_format_known_length(int n);

/** Plain binary string, first bit received first. No separators. */
void wiegand_format_binary_plain(const volatile bool* bits, int n, char* out, size_t size);

/**
 * Binary string grouped for the Flipper screen: nibbles counted from the LAST
 * bit received, 16 bits per line. Each group lines up with one digit of the
 * right-justified hex value.
 */
void wiegand_format_binary_grouped(const volatile bool* bits, int n, char* out, size_t size);

/**
 * Hex value of the bitstream.
 * Right-justified pads with zero bits in front of the first bit (most PACS).
 * Left-justified pads with zero bits after the last bit.
 * Both are the same when the bit count is a multiple of 4.
 */
void wiegand_format_hex(
    const volatile bool* bits,
    int n,
    bool left_justified,
    char* out,
    size_t size);

/**
 * Field decode for the lengths we recognise. This is a GUESS based on the bit
 * count alone: the raw bits are the truth. Multi-line text, no trailing
 * newline. Empty string when there is nothing to say.
 */
void wiegand_format_decode(const volatile bool* bits, int n, char* out, size_t size);
